(7686945, 1259034, 99263, '<td valign="top">Very out of focus</td>', 'Very out of focus', '2021-02-15 01:50:31.000000', NULL, 1),
(7686946, 1259025, 99263, '<td valign="top">Nice grouping but something odd going on with largest elephants trunk and the legs of both adult elephants, like you were trying to correct some imperfections.</td>', 'Nice grouping but something odd going on with largest elephants trunk and the legs of both adult elephants, like you were trying to correct some imperfections.', '2021-02-15 01:55:53.000000', NULL, 1),
(7686958, 1259026, 4008, '<td valign="top">It needs a white balance correction, snow is not blue normally. I also find the person and red coat to overwhelming in the shot.  The snow in the air is too obviously fake, it is mirrored symmetrical in the image.... oh, wait, the whole lane is mirrored, including the trees.</td>', 'It needs a white balance correction, snow is not blue normally. I also find the person and red coat to overwhelming in the shot.  The snow in the air is too obviously fake, it is mirrored symmetrical in the image.... oh, wait, the whole lane is mirrored, including the trees.', '2021-02-15 03:55:30.000000', NULL, 1),
(7686961, 1258768, 4008, '<td valign="top">What a gorgeous bird. The head seems just very slightly out of focus (but still enough), the rest of the body is perfect. The finishing and texture of the green around the bird works very well.</td>', 'What a gorgeous bird. The head seems just very slightly out of focus (but still enough), the rest of the body is perfect. The finishing and texture of the green around the bird works very well.', '2021-02-15 04:17:40.000000', NULL, 1),
(7686962, 1259076, 4008, '<td valign="top">What a great model again!!! The soft finishing of this image is great as well.</td>', 'What a great model again!!! The soft finishing of this image is great as well.', '2021-02-15 04:19:28.000000', NULL, 1),
(7686963, 1259050, 4008, '<td valign="top">I love the tones in this image. In colour this might have been just a beautiful landscape but you added something special.</td>', 'I love the tones in this image. In colour this might have been just a beautiful landscape but you added something special.', '2021-02-15 04:20:16.000000', NULL, 1),
(7686964, 1258286, 4008, '<td valign="top">Wow, great depth and impressive sky and landscape. Love the wide angle.</td>', 'Wow, great depth and impressive sky and landscape. Love the wide angle.', '2021-02-15 04:22:15.000000', NULL, 1),
(7686966, 1259011, 4008, '<td valign="top">Nicely done. Maybe you should have put it slightly more at an angle to enhance the illusion it is driving in the street.</td>', 'Nicely done. Maybe you should have put it slightly more at an angle to enhance the illusion it is driving in the street.', '2021-02-15 04:26:55.000000', NULL, 1),
(7686967, 1258304, 4008, '<td valign="top">Lovely warm colours. Great focus on the grasshopper. Lovely lines running through the image. No doubt a winner again.</td>', 'Lovely warm colours. Great focus on the grasshopper. Lovely lines running through the image. No doubt a winner again.', '2021-02-15 04:31:07.000000', NULL, 1),
(7686968, 1258949, 4008, '<td valign="top">Art. Lovely warm tones, great movement and lines. Print it, frame it, enjoy it, every day.</td>', 'Art. Lovely warm tones, great movement and lines. Print it, frame it, enjoy it, every day.', '2021-02-15 04:32:20.000000', NULL, 1),
(7686970, 1259048, 4008, '<td valign="top">At first I did not like the grain finish, but the longer I look the more I like it. Like a painting. Nice rural scene.</td>', 'At first I did not like the grain finish, but the longer I look the more I like it. Like a painting. Nice rural scene.', '2021-02-15 04:34:53.000000', NULL, 1),
(7686971, 1259079, 4008, '<td valign="top">Is there is meaning/message in this image? Memories of Africa?  Or is this to show editing skills? I think it is very well done technically. The only thing strange is the horizontal line from shoulder to shoulder. Why?</td>', 'Is there is meaning/message in this image? Memories of Africa?  Or is this to show editing skills? I think it is very well done technically. The only thing strange is the horizontal line from shoulder to shoulder. Why?', '2021-02-15 04:36:05.000000', NULL, 1),
(7686972, 1259084, 4008, '<td valign="top">I don''t like the editing in this one at all. Too much blow out highlights, the dark lines around the swans, the plastic feel to the water. Must have been a beautiful scene, but nor anymore. Sorry.</td>', 'I don''t like the editing in this one at all. Too much blow out highlights, the dark lines around the swans, the plastic feel to the water. Must have been a beautiful scene, but nor anymore. Sorry.', '2021-02-15 04:38:13.000000', NULL, 1),
